mapper.select:
SELECT COALESCE(sum(total_amount), 0)::bigint AS amount,
       count(*) AS count
  FROM sales
 WHERE status = 'COMPLETED'
   AND sold_at >= #{from}
   AND sold_at < #{to}

   AND store_id = #{storeId}

SELECT d.day::date AS date, COALESCE(sum(s.total_amount), 0)::bigint AS amount FROM generate_series(#{startDate}::date, #{endDate}::date, interval '1 day') AS d(day) LEFT JOIN sales s ON s.status = 'COMPLETED' AND (s.sold_at AT TIME ZONE 'Asia/Seoul')::date = d.day::date
AND s.store_id = #{storeId}
GROUP BY d.day ORDER BY d.day

SELECT
(SELECT count(*) FROM stocks WHERE store_id = #{storeId} AND quantity >= 1) AS in_stock_product_count,
(SELECT count(*) FROM (SELECT product_id FROM stocks GROUP BY product_id HAVING sum(quantity) >= 1) t) AS in_stock_product_count,
(SELECT count(*) FROM stocks st JOIN products p ON p.id = st.product_id WHERE p.status = 'ACTIVE' AND st.quantity < st.safety_stock
AND st.store_id = #{storeId}
) AS shortage_count

SELECT st.store_id, s.store_name, st.product_id, p.product_code, p.product_name, st.quantity, st.safety_stock, st.safety_stock - st.quantity AS shortage_quantity FROM stocks st JOIN stores s ON s.id = st.store_id JOIN products p ON p.id = st.product_id WHERE p.status = 'ACTIVE' AND st.quantity < st.safety_stock
AND st.store_id = #{storeId}
ORDER BY shortage_quantity DESC, s.store_name, p.product_code LIMIT #{limit}

SELECT id, sale_number, sold_at, total_amount, status
  FROM sales

    store_id = #{storeId}

 ORDER BY sold_at DESC, id DESC
 LIMIT #{limit}

SELECT po.id, po.order_number, sp.supplier_name, po.ordered_at, po.status
  FROM purchase_orders po
  JOIN suppliers sp ON sp.id = po.supplier_id

    po.store_id = #{storeId}

 ORDER BY po.ordered_at DESC, po.id DESC
 LIMIT #{limit}
